"""Fetch the pinned Microsoft SDK math input; generated bytes stay under build/."""
import hashlib
import urllib.request
import zipfile

NAMES = "asinf atan2f cos cosf exp expf fmodf frexp log log10 log10f pow powf sinf sqrtf tanf".split()

SDK_VERSION = '10.0.26100.3916'

SDK_URL = f'https://api.nuget.org/v3-flatcontainer/microsoft.windows.sdk.cpp/{SDK_VERSION}/microsoft.windows.sdk.cpp.{SDK_VERSION}.nupkg'

SDK_SHA256 = '21dfb5db3397425ee428e0fd54cedc51af52ddd10c82433a7cdb483ecbb284ad'

DLL_MEMBER = 'c/Redist/10.0.26100.0/ucrt/DLLs/x64/ucrtbase.dll'

def digest(data):
    return hashlib.sha256(data).hexdigest()

def microsoft_ucrt(oracle):
    package = oracle / 'sdk-cpp.nupkg'
    oracle.mkdir(parents=True, exist_ok=True)
    if not package.exists():
        urllib.request.urlretrieve(SDK_URL, package)
    assert digest(package.read_bytes()) == SDK_SHA256, 'SDK package hash changed'
    directory = oracle / 'native'
    directory.mkdir(exist_ok=True)
    with zipfile.ZipFile(package) as archive:
        dll = archive.read(DLL_MEMBER)
    (directory / 'ss_ucrt.dll').write_bytes(dll)
    return directory, dll
